Here is the commit message:
Monitor: fix for regression with container devices

This patch fixes 2 problems introduced by commit 9a518d8: not closing a
file descriptor and ignoring container devices. Array state is always
"inactive" for containers, so we make sure that the device is not a
container by reading also the "level" sysfs entry.

Signed-off-by: Artur Paszkiewicz <artur.paszkiewicz@intel.com>
Reviewed-by: Pawel Baldysiak <pawel.baldysiak@intel.com>
Signed-off-by: NeilBrown <neilb@suse.de>

Here is the root cause:
The bug was caused by the failure to properly check if a device was a container, leading to incorrect handling of inactive devices. Specifically, the code did not read the "level" sysfs entry to determine the device type, which resulted in not closing a file descriptor and potentially issuing false alerts for container devices that should be ignored.

Here is the patch:

 static int check_array(struct state *st, struct mdstat_ent *mdstat,
 		       int test, struct alert_info *ainfo,
 		       int increments, char *prefer)
 {
 	/* Update the state 'st' to reflect any changes shown in mdstat,
 	 * or found by directly examining the array, and return
 	 * '1' if the array is degraded, or '0' if it is optimal (or dead).
 	 */
 	struct { int state, major, minor; } info[MAX_DISKS];
 	mdu_array_info_t array;
 	struct mdstat_ent *mse = NULL, *mse2;
 	char *dev = st->devname;
 	int fd = -1;
 	int i;
 	int remaining_disks;
 	int last_disk;
 	int new_array = 0;

 	if (test)
 		alert("TestMessage", dev, NULL, ainfo);
 	if (st->devnm[0])
 		fd = open("/sys/block", O_RDONLY|O_DIRECTORY);
 	if (fd >= 0) {
 		/* Don't open the device unless it is present and
 		 * active in sysfs.
 		 */
 		char buf[10];
 		close(fd);
 		fd = sysfs_open(st->devnm, NULL, "array_state");
 		if (fd < 0 ||
 		    read(fd, buf, 10) < 5 ||
 		    strncmp(buf,"clear",5) == 0 ||
 		    strncmp(buf,"inact",5) == 0) {
 			if (fd >= 0)
 				close(fd);
-			if (!st->err)
-				alert("DeviceDisappeared", dev, NULL, ainfo);
-			st->err++;
-			return 0;
+			fd = sysfs_open(st->devnm, NULL, "level");
+			if (fd < 0 || read(fd, buf, 10) != 0) {
+				if (fd >= 0)
+					close(fd);
+				if (!st->err)
+					alert("DeviceDisappeared", dev, NULL, ainfo);
+				st->err++;
+				return 0;
+			}
 		}
+		close(fd);
 	}
 	fd = open(dev, O_RDONLY);
 	if (fd < 0) {
 		if (!st->err)
 			alert("DeviceDisappeared", dev, NULL, ainfo);
 		st->err++;
 		return 0;
 	}
 	fcntl(fd, F_SETFD, FD_CLOEXEC);
 	if (ioctl(fd, GET_ARRAY_INFO, &array)<0) {
 		if (!st->err)
 			alert("DeviceDisappeared", dev, NULL, ainfo);
 		st->err++;
 		close(fd);
 		return 0;
 	}
 	/* It's much easier to list what array levels can't
 	 * have a device disappear than all of them that can
 	 */
 	if (array.level == 0 || array.level == -1) {
 		if (!st->err && !st->from_config)
 			alert("DeviceDisappeared", dev, "Wrong-Level", ainfo);
 		st->err++;
 		close(fd);
 		return 0;
 	}
 	if (st->devnm[0] == 0)
 		strcpy(st->devnm, fd2devnm(fd));

 	for (mse2 = mdstat ; mse2 ; mse2=mse2->next)
 		if (strcmp(mse2->devnm, st->devnm) == 0) {
 			mse2->devnm[0] = 0; /* flag it as "used" */
 			mse = mse2;
 		}

 	if (!mse) {
 		/* duplicated array in statelist
 		 * or re-created after reading mdstat*/
 		st->err++;
 		close(fd);
 		return 0;
 	}
 	/* this array is in /proc/mdstat */
 	if (array.utime == 0)
 		/* external arrays don't update utime, so
 		 * just make sure it is always different. */
 		array.utime = st->utime + 1;;

 	if (st->err) {
 		/* New array appeared where previously had an error */
 		st->err = 0;
 		st->percent = RESYNC_NONE;
 		new_array = 1;
 		alert("NewArray", st->devname, NULL, ainfo);
 	}

 	if (st->utime == array.utime &&
 	    st->failed == array.failed_disks &&
 	    st->working == array.working_disks &&
 	    st->spare == array.spare_disks &&
 	    (mse == NULL  || (
 		    mse->percent == st->percent
 		    ))) {
 		close(fd);
 		if ((st->active < st->raid) && st->spare == 0)
 			return 1;
 		else
 			return 0;
 	}
 	if (st->utime == 0 && /* new array */
 	    mse->pattern && strchr(mse->pattern, '_') /* degraded */
 		)
 		alert("DegradedArray", dev, NULL, ainfo);

 	if (st->utime == 0 && /* new array */
 	    st->expected_spares > 0 &&
 	    array.spare_disks < st->expected_spares)
 		alert("SparesMissing", dev, NULL, ainfo);
 	if (st->percent < 0 && st->percent != RESYNC_UNKNOWN &&
 	    mse->percent >= 0)
 		alert("RebuildStarted", dev, NULL, ainfo);
 	if (st->percent >= 0 &&
 	    mse->percent >= 0 &&
 	    (mse->percent / increments) > (st->percent / increments)) {
 		char percentalert[15]; // "RebuildNN" (10 chars) or "RebuildStarted" (15 chars)

 		if((mse->percent / increments) == 0)
 			snprintf(percentalert, sizeof(percentalert), "RebuildStarted");
 		else
 			snprintf(percentalert, sizeof(percentalert), "Rebuild%02d", mse->percent);

 		alert(percentalert, dev, NULL, ainfo);
 	}

 	if (mse->percent == RESYNC_NONE &&
 	    st->percent >= 0) {
 		/* Rebuild/sync/whatever just finished.
 		 * If there is a number in /mismatch_cnt,
 		 * we should report that.
 		 */
 		struct mdinfo *sra =
 			sysfs_read(-1, st->devnm, GET_MISMATCH);
 		if (sra && sra->mismatch_cnt > 0) {
 			char cnt[80];
 			snprintf(cnt, sizeof(cnt),
 				 " mismatches found: %d (on raid level %d)",
 				sra->mismatch_cnt, array.level);
 			alert("RebuildFinished", dev, cnt, ainfo);
 		} else
 			alert("RebuildFinished", dev, NULL, ainfo);
 		if (sra)
 			free(sra);
 	}
 	st->percent = mse->percent;

 	remaining_disks = array.nr_disks;
 	for (i=0; i<MAX_DISKS && remaining_disks > 0;
 	     i++) {
 		mdu_disk_info_t disc;
 		disc.number = i;
 		if (ioctl(fd, GET_DISK_INFO, &disc) >= 0) {
 			info[i].state = disc.state;
 			info[i].major = disc.major;
 			info[i].minor = disc.minor;
 			if (disc.major || disc.minor)
 				remaining_disks --;
 		} else
 			info[i].major = info[i].minor = 0;
 	}
 	last_disk = i;

 	if (mse->metadata_version &&
 	    strncmp(mse->metadata_version, "external:", 9) == 0 &&
 	    is_subarray(mse->metadata_version+9)) {
 		char *sl;
 		strcpy(st->parent_devnm,
 		       mse->metadata_version+10);
 		sl = strchr(st->parent_devnm, '/');
 		if (sl)
 			*sl = 0;
 	} else
 		st->parent_devnm[0] = 0;
 	if (st->metadata == NULL &&
 	    st->parent_devnm[0] == 0)
 		st->metadata = super_by_fd(fd, NULL);

 	close(fd);

 	for (i=0; i<MAX_DISKS; i++) {
 		mdu_disk_info_t disc = {0,0,0,0,0};
 		int newstate=0;
 		int change;
 		char *dv = NULL;
 		disc.number = i;
 		if (i < last_disk &&
 		    (info[i].major || info[i].minor)) {
 			newstate = info[i].state;
 			dv = map_dev_preferred(
 				info[i].major, info[i].minor, 1,
 				prefer);
 			disc.state = newstate;
 			disc.major = info[i].major;
 			disc.minor = info[i].minor;
 		} else
 			newstate = (1 << MD_DISK_REMOVED);

 		if (dv == NULL && st->devid[i])
 			dv = map_dev_preferred(
 				major(st->devid[i]),
 				minor(st->devid[i]), 1, prefer);
 		change = newstate ^ st->devstate[i];
 		if (st->utime && change && !st->err && !new_array) {
 			if ((st->devstate[i]&change)&(1<<MD_DISK_SYNC))
 				alert("Fail", dev, dv, ainfo);
 			else if ((newstate & (1<<MD_DISK_FAULTY)) &&
 				 (disc.major || disc.minor) &&
 				 st->devid[i] == makedev(disc.major, disc.minor))
 				alert("FailSpare", dev, dv, ainfo);
 			else if ((newstate&change)&(1<<MD_DISK_SYNC))
 				alert("SpareActive", dev, dv, ainfo);
 		}
 		st->devstate[i] = newstate;
 		st->devid[i] = makedev(disc.major, disc.minor);
 	}
 	st->active = array.active_disks;
 	st->working = array.working_disks;
 	st->spare = array.spare_disks;
 	st->failed = array.failed_disks;
 	st->utime = array.utime;
 	st->raid = array.raid_disks;
 	st->err = 0;
 	if ((st->active < st->raid) && st->spare == 0)
 		return 1;
 	return 0;
 }



